DROP TABLE IF EXISTS "core_turf" CASCADE;
CREATE TABLE "core_turf" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(100) NOT NULL,
  "location" varchar(255) NOT NULL,
  "latitude" double precision DEFAULT NULL,
  "longitude" double precision DEFAULT NULL,
  "price_per_hour" int NOT NULL,
  "description" text,
  "games" json NOT NULL,
  "amenities" json NOT NULL,
  "features" json NOT NULL,
  "slots" json NOT NULL,
  "is_popular" boolean NOT NULL,
  "priority" int NOT NULL,
  "vendor_code" varchar(20) NOT NULL,
  "is_approved" boolean NOT NULL,
  "role" varchar(20) DEFAULT NULL,
  "created_at" timestamp with time zone NOT NULL,
  "owner_id" char(32) DEFAULT NULL,
  "vendor_id" bigint DEFAULT NULL,
  "is_maintenance" boolean NOT NULL,
  "retire" int NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "core_turf_owner_id_70ef4d62_fk_core_appuser_id" FOREIGN KEY ("owner_id") REFERENCES "core_appuser" ("id"),
  CONSTRAINT "core_turf_vendor_id_430203c9_fk_core_vendor_id" FOREIGN KEY ("vendor_id") REFERENCES "core_vendor" ("id")
);

